"""Exploratory paired anchor effects versus supplier risk, without new sessions."""

import hashlib
import json
import random
import statistics as st
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'out/company-analysis/round2'


def ranks(values):
    ordered = sorted(values)
    return [1 + (ordered.index(v) + len(ordered) - 1 - ordered[::-1].index(v)) / 2 for v in values]


def correlation(x, y):
    if len(x) < 3 or len(set(x)) < 2 or len(set(y)) < 2:
        return None
    return st.correlation(ranks(x), ranks(y))


def interval(values):
    if len(values) < 2:
        return None
    rng = random.Random(601)
    boot = sorted(st.mean(rng.choices(values, k=len(values))) for _ in range(4000))
    return [boot[100], boot[3899]]


def aggregate(rows):
    by_supplier = {}
    for r in rows:
        by_supplier.setdefault(r['supplier_id'], []).append(r)
    effects = [st.mean(x['delta_saving_pp'] for x in group) for group in by_supplier.values()]
    return {
        'suppliers': len(by_supplier), 'paired_cases': len(rows),
        'saving20_pct': st.mean(r['saving20_pct'] for r in rows),
        'saving30_pct': st.mean(r['saving30_pct'] for r in rows),
        'delta_saving_pp': st.mean(effects),
        'supplier_bootstrap_95_interval_pp': interval(effects),
        'deals20': sum(r['deal20'] for r in rows),
        'deals30': sum(r['deal30'] for r in rows),
        'lost_deals': sum(r['deal20'] and not r['deal30'] for r in rows),
        'gained_deals': sum(r['deal30'] and not r['deal20'] for r in rows),
        'better30': sum(r['delta_saving_pp'] > 1e-9 for r in rows),
        'worse30': sum(r['delta_saving_pp'] < -1e-9 for r in rows),
    }


def main():
    baseline = json.loads((OUT.parent / 'baseline.json').read_text())
    profiles = {}
    for d in baseline['dossiers']:
        f, sc = d['profile']['financials'][0], d['profile']['scorecard'][0]
        profiles[d['supplier_id']] = {
            'name': d['profile']['supplier']['name'],
            'credit_index': f['credit_index'], 'equity_ratio_pct': f['equity_ratio_pct'],
            'credit_deterioration': f['credit_index'] - f['credit_index_12m_ago'],
            'otd_pct': sc['otd_pct'], 'ppm': sc['ppm'], 'score': sc['score'],
            'colour': sc['colour'], 'category': d['profile']['supplier']['category'],
        }
    med_credit = st.median(p['credit_index'] for p in profiles.values())
    med_equity = st.median(p['equity_ratio_pct'] for p in profiles.values())
    report = {'protocol': {
        'unit': 'Paired 30% minus 20% outcome; inference resamples supplier means, not repeated cases.',
        'financial_groups': f'Credit index >=300 existing heuristic; all-46 median credit={med_credit}; median equity={med_equity}.',
        'interpretation': 'Exploratory association in synthetic outcomes, not observed supplier willingness or causation. Hidden supplier economics were generated independently of profile risk.',
        'bootstrap': '4000 supplier resamples, seed 601, percentile 95% intervals, no generalization guarantee.',
        'correlation': 'Spearman with ties; 1999 two-sided permutations; descriptive unadjusted p-values across multiple exploratory comparisons.',
        'training': 'No training, no retuning, no online sessions. Existing 19 suppliers only.',
    }, 'datasets': {}}
    specs = [('original_four_behaviors', 'evaluation.jsonl', 'menu', 'menu_anchor30_exploratory'),
             ('fresh_seeds_five_behaviors', 'adaptive-runs.jsonl', 'menu20', 'menu30')]
    for name, filename, low, high in specs:
        raw = [json.loads(line) for line in (OUT / filename).read_text().splitlines()]
        keys = lambda r: (r['supplier_id'], r['seed'], r['persona'])
        lows = {keys(r): r for r in raw if r['strategy'] == low}
        highs = {keys(r): r for r in raw if r['strategy'] == high}
        assert lows.keys() == highs.keys()
        paired = []
        for k, a in lows.items():
            b = highs[k]
            assert a['no_deal_cost'] == b['no_deal_cost'] and a['shock'] == b['shock']
            paired.append({'supplier_id': k[0], 'seed': k[1], 'persona': k[2], 'shock': a['shock'],
                           'saving20_pct': 100 * a['saving_vs_no_deal'], 'saving30_pct': 100 * b['saving_vs_no_deal'],
                           'delta_saving_pp': 100 * (b['saving_vs_no_deal'] - a['saving_vs_no_deal']),
                           'deal20': bool(a['result']['deal']), 'deal30': bool(b['result']['deal'])})
        suppliers = []
        for sid in sorted(lows_key[0] for lows_key in lows):
            if any(s['supplier_id'] == sid for s in suppliers):
                continue
            rr = [r for r in paired if r['supplier_id'] == sid]
            suppliers.append({'supplier_id': sid, **profiles[sid], **aggregate(rr)})
        correlations = {}
        for field in ['credit_index', 'equity_ratio_pct', 'credit_deterioration', 'otd_pct', 'ppm', 'score']:
            x = [s[field] for s in suppliers]
            y = [s['delta_saving_pp'] for s in suppliers]
            rho = correlation(x, y)
            rng = random.Random(1701)
            count = 1
            for _ in range(1999):
                yy = rng.sample(y, len(y))
                perm = correlation(x, yy)
                count += rho is not None and perm is not None and abs(perm) >= abs(rho) - 1e-12
            correlations[field] = {'spearman_rho': rho, 'unadjusted_permutation_p': count / 2000 if rho is not None else None}
        predicates = {
            'credit_at_least_300': lambda p: p['credit_index'] >= 300,
            'credit_below_300': lambda p: p['credit_index'] < 300,
            'credit_at_least_all_supplier_median': lambda p: p['credit_index'] >= med_credit,
            'credit_below_all_supplier_median': lambda p: p['credit_index'] < med_credit,
            'equity_below_all_supplier_median': lambda p: p['equity_ratio_pct'] < med_equity,
            'equity_at_least_all_supplier_median': lambda p: p['equity_ratio_pct'] >= med_equity,
            **{colour: lambda p, c=colour: p['colour'] == c for colour in ['red', 'amber', 'green']},
        }
        groups = {}
        for label, pred in predicates.items():
            rr = [r for r in paired if pred(profiles[r['supplier_id']])]
            if rr:
                groups[label] = aggregate(rr)
        report['datasets'][name] = {
            'overall': aggregate(paired), 'groups': groups, 'correlations': correlations,
            'by_persona': {p: aggregate([r for r in paired if r['persona'] == p]) for p in sorted({r['persona'] for r in paired})},
            'by_shock': {p: aggregate([r for r in paired if r['shock'] == p]) for p in sorted({r['shock'] for r in paired})},
            'excluding_impossible': aggregate([r for r in paired if r['shock'] != 'impossible']),
            'suppliers': suppliers, 'paired_cases': paired,
            'input_sha256': hashlib.sha256((OUT / filename).read_bytes()).hexdigest(),
        }
    (OUT / 'anchor-risk-analysis.json').write_text(json.dumps(report, indent=2) + '\n')
